import{_ as t,o as s,c as a,ai as o}from"./chunks/framework.BBSijY9B.js";const u=JSON.parse('{"title":"开发者","description":"开发者如何用 Grok Bot 复现 Bug、整理 Issue、审查 PR、盯 CI，以及设置安全边界。","frontmatter":{"related":["/templates/code-reviewer","/templates/team-dev-squad","/basics/safety-approvals"],"title":"开发者","description":"开发者如何用 Grok Bot 复现 Bug、整理 Issue、审查 PR、盯 CI，以及设置安全边界。","section":"roles","order":5,"tags":["角色","开发者","GitHub","代码"],"sources":["https://x.ai/news/introducing-grok-bot","https://docs.x.ai/grok-bot/skills-routines-and-automations","https://docs.x.ai/grok-bot/approvals-security-and-privacy"],"wordCount":391,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"开发者 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"开发者如何用 Grok Bot 复现 Bug、整理 Issue、审查 PR、盯 CI，以及设置安全边界。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/roles/developers"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/roles-developers-8344c2fde3.png"}],["meta",{"property":"og:image:alt","content":"开发者 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"开发者 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"开发者如何用 Grok Bot 复现 Bug、整理 Issue、审查 PR、盯 CI，以及设置安全边界。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/roles-developers-8344c2fde3.png"}],["meta",{"name":"twitter:image:alt","content":"开发者 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/roles/developers"}]]},"headers":[],"relativePath":"roles/developers.md","filePath":"roles/developers.md","lastUpdated":1792485206000}'),n={name:"roles/developers.md"};function p(i,e,l,r,c,d){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="开发者" tabindex="-1">开发者 <a class="header-anchor" href="#开发者" aria-label="Permalink to &quot;开发者&quot;">​</a></h1><p>对开发者来说，Grok Bot 的云电脑就是一台随时待命的开发机：能克隆仓库、跑测试、开浏览器复现问题。官方介绍中提到的一个内部用法是：工程 Bot 在产品界面里复现 Bug、提交工单，再把修复交给另一个调试 Bot。</p><h2 id="典型工作" tabindex="-1">典型工作 <a class="header-anchor" href="#典型工作" aria-label="Permalink to &quot;典型工作&quot;">​</a></h2><ul><li>按 Issue 描述复现 Bug，整理复现步骤和截图。</li><li>整理和分类新 Issue，补全缺失信息。</li><li>审查 Pull Request，列出问题和建议。</li><li>盯 CI 失败，定位原因并给出修复思路。</li><li>写脚本、做小工具、更新文档。</li></ul><h2 id="示例提示词" tabindex="-1">示例提示词 <a class="header-anchor" href="#示例提示词" aria-label="Permalink to &quot;示例提示词&quot;">​</a></h2><p><strong>复现 Bug</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看一下 GitHub 上 my-org/web-app 的 Issue #482。在云电脑上拉取代码、本地启动，</span></span>
<span class="line"><span>按描述复现问题。整理一份复现包：环境、步骤、实际结果、期望结果、截图和相关日志。</span></span>
<span class="line"><span>先不要改代码，也不要在 Issue 下评论。</span></span></code></pre></div><p><strong>Issue 分拣</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>列出 my-org/web-app 过去 7 天新开的 Issue，按&quot;Bug / 需求 / 提问 / 重复&quot;分类，</span></span>
<span class="line"><span>重复的指出原 Issue 编号，信息不全的写出需要追问什么。给我一张表即可。</span></span></code></pre></div><p><strong>PR 审查</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>审查 PR #317：关注逻辑错误、边界情况、缺失的测试和安全隐患。</span></span>
<span class="line"><span>只列出值得修改的问题，按严重程度排序。审查意见先给我看，不要直接提交评论。</span></span></code></pre></div><p><strong>CI 失败排查</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main 分支最近一次 CI 失败了。看看是哪个任务、哪个测试挂的，</span></span>
<span class="line"><span>判断是代码问题还是环境不稳定，给出修复建议。</span></span></code></pre></div><h2 id="推荐例程" tabindex="-1">推荐例程 <a class="header-anchor" href="#推荐例程" aria-label="Permalink to &quot;推荐例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当 GitHub 上 my-org/web-app 出现带&quot;needs-repro&quot;标签的新 Issue 时，</span></span>
<span class="line"><span>自动尝试复现，把复现包发到这个对话里。不要在 GitHub 上评论或修改标签。</span></span></code></pre></div><p>事件触发需要相应的账号集成，支持范围以官方最新说明为准。</p><div class="tip custom-block"><p class="custom-block-title">本地开发环境</p><p>如果项目只能在你本机跑，可以授权 Bot 在你注册的本地电脑上执行命令，默认每条都要你确认。详见<a href="/basics/local-computer">在自己电脑上干活</a>。</p></div><div class="warning custom-block"><p class="custom-block-title">常见坑</p><ul><li><strong>给 Bot 生产环境的权限</strong>：合并到主分支、部署、改线上配置，都应放在审批之后。</li><li><strong>命令行凭证共享</strong>：云电脑上的 Git 凭证、云服务密钥对所有 Bot 可见，尽量用权限受限的令牌。</li><li><strong>过度宽泛的自动允许规则</strong>：只对明确的只读命令（如查看状态）设自动允许。</li><li><strong>测试运行真的会推代码</strong>：带写操作的例程，测试时用分支或测试仓库。</li></ul></div>`,18)])])}const h=t(n,[["render",p]]);export{u as __pageData,h as default};
